/* Identidade Flora Digital: azul escuro #14283C, amarelo escuro #B88A24, verde oliva #5E6B2E, off-white #F6F3EC, grafite */
:root{
  --bg:#F6F3EC;--fg:#14283C;--muted:#5C6A75;--line:#D9D3C4;--card:#FFFFFF;
  --tit:#14283C;--det:#5E6B2E;--accent:#14283C;--accent-fg:#F6F3EC;
  --pill:#14283C;--pill-fg:#F6F3EC;--sage:#B88A24;--stage:#0E1B2A;
  --aj-bg:#F6E4CF;--aj-fg:#8A4B12;--aj-bd:#B88A24;
  --ok-bg:#E8ECD3;--ok-fg:#3F4A1B;--ok-bd:#5E6B2E;
  --no-bg:#373B3F;--no-fg:#F6F3EC;--no-bd:#373B3F;
  --display:'Cormorant Garamond',Georgia,serif;
  --body:'Lora',Georgia,serif;
  --serif:'Cormorant Garamond',Georgia,serif;
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#0E1B2A;--fg:#F1ECDF;--muted:#9FAAB3;--line:#26384B;--card:#14283C;
    --tit:#F1ECDF;--det:#B7C27E;--accent:#D4A93E;--accent-fg:#0E1B2A;
    --pill:#D4A93E;--pill-fg:#0E1B2A;--sage:#D4A93E;--stage:#07101A;
    --aj-bg:#47301A;--aj-fg:#F0C48E;--aj-bd:#D4A93E;
    --ok-bg:#2B3318;--ok-fg:#D3E0A0;--ok-bd:#B7C27E;
    --no-bg:#4A4F54;--no-fg:#F1ECDF;--no-bd:#8C9399;
    color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#0E1B2A;--fg:#F1ECDF;--muted:#9FAAB3;--line:#26384B;--card:#14283C;
  --tit:#F1ECDF;--det:#B7C27E;--accent:#D4A93E;--accent-fg:#0E1B2A;
  --pill:#D4A93E;--pill-fg:#0E1B2A;--sage:#D4A93E;--stage:#07101A;
  --aj-bg:#47301A;--aj-fg:#F0C48E;--aj-bd:#D4A93E;
  --ok-bg:#2B3318;--ok-fg:#D3E0A0;--ok-bd:#B7C27E;
  --no-bg:#4A4F54;--no-fg:#F1ECDF;--no-bd:#8C9399;
  color-scheme:dark;
}

